#include <string>
#include <string_view>
#include <vector>

class ILogger
{
public:
    virtual ~ILogger() = default;
    virtual void log(std::string_view message) = 0;
};

class MemoryLogger : public ILogger
{
public:
    void log(std::string_view message) override { m_lines.emplace_back(message); }
    const std::vector<std::string>& lines() const { return m_lines; }

private:
    std::vector<std::string> m_lines{};
};

void runJob(ILogger& logger, int steps)
{
    logger.log("start");
    for (int i{ 1 }; i <= steps; ++i)
    {
        logger.log("step " + std::to_string(i));
    }
    logger.log("done");
}

unitTests:
static_assert(std::is_abstract_v<ILogger>, "ILogger::log should be pure virtual (= 0)");
static_assert(std::has_virtual_destructor_v<ILogger>);
static_assert(std::is_base_of_v<ILogger, MemoryLogger> && !std::is_abstract_v<MemoryLogger>);

struct CountingLogger : ILogger { int count{ 0 }; void log(std::string_view) override { ++count; } };

TEST("MemoryLogger keeps the lines") { MemoryLogger m{}; m.log("a"); m.log("b"); CHECK_EQ(m.lines(), (std::vector<std::string>{ "a", "b" })); }
TEST("runJob") { MemoryLogger m{}; runJob(m, 2); CHECK_EQ(m.lines(), (std::vector<std::string>{ "start", "step 1", "step 2", "done" })); }
TEST("runJob works with any logger") { CountingLogger c{}; runJob(c, 5); CHECK_EQ(c.count, 7); }

